mapper.select:
select id, claim_id, entry_kind, event_key, batch_id, merchant_id, source_type, source_id, receiver_type, receiver_id,
       gross_amount, commission_amount, settlement_amount, status, fail_reason,
       idempotency_key, create_time, update_time
from settlement_detail

    and batch_id = #{batchId}
    and merchant_id = #{merchantId}
    and status = #{status}
    and source_type = #{sourceType}

order by id desc

select count(1)
from settlement_detail
where source_type = #{sourceType}
  and source_id = #{sourceId}

mapper.update:
update settlement_detail
set status = 2, fail_reason = '退款作废', update_time = now()
where source_type = #{sourceType}
  and source_id = #{sourceId}
  and batch_id = 0
  and status = 0

mapper.select:
select d.id as detailId, r.id as registrationId, a.id as activityId, a.topic_id as topicId, coalesce(a.name, r.activity_title) as activityTitle, r.ticket_name as ticketName, coalesce(d.update_time, d.create_time) as occurredAt, d.settlement_amount as feeAmount, case when c.source_contract_type = 'MERCHANT_CHAPTER_OFFER' then d.gross_amount else o.fixed_fee end as unitFee, (select coalesce(sum(adj.settlement_amount), 0) from settlement_detail adj join refund_application ra on ra.id = adj.source_id and ra.source_type = 'registration' where adj.source_type = 'refund' and adj.status = 1 and adj.receiver_type = 'coop_merchant' and adj.receiver_id = d.receiver_id and ra.source_id = r.id) as clawbackAmount, d.status as status from settlement_detail d join cms_registration r on r.id = d.source_id join cms_activity a on a.id = r.owner_id left join settlement_claim c on c.id = d.claim_id left join coop_order o on c.source_contract_type = 'COOP_ORDER' and o.id = c.source_contract_id where d.source_type = 'registration' and d.receiver_type = 'coop_merchant' and d.receiver_id = #{merchantMemberId} and d.status = 1 and r.owner_type = 2
and a.id = #{activityId}
order by d.id desc

select gv.activity_id as activityId, gv.merchant_member_id as merchantMemberId, a.end_date as endDate, o.fixed_fee * ( select coalesce(sum(case when t.product_type = 2 then 1 when seat.n > 0 then seat.n else coalesce(r.order_num, 1) end), 0) from cms_registration r left join (select s.registration_id, count(1) as n from cms_registration_seat s where s.status = 1 group by s.registration_id) seat on seat.registration_id = r.id where r.owner_type = 2 and r.owner_id = gv.activity_id and r.payment_status = 2 and r.registration_status = 2 and (case when t.product_type = 2 then exists ( select 1 from redemption rd where rd.registration_id = r.id and rd.topic_id = t.id and rd.merchant_id = gv.merchant_member_id and rd.status = 'ACTIVE') else end) and not exists ( select 1 from refund_application ra where ra.source_type = 'registration' and ra.source_id = r.id and ra.status = 1 and ra.del_flag = 0) ) as amount from ( select gv.activity_id, gv.merchant_member_id, gv.coop_order_id from coop_group_verify gv join cms_activity ga on ga.id = gv.activity_id left join cms_topic gt on gt.id = ga.topic_id where gt.product_type is null or gt.product_type != 2 union all select a.id, o.to_id, o.id from cms_activity a join cms_topic t on t.id = a.topic_id and t.product_type = 2 and a.club_id = t.club_id and a.club_id > 0 join topic_sale_snapshot ss on ss.topic_id = t.id and ss.schema_version = 'CANONICAL_15_V1' and json_unquote(json_extract(ss.canonical_json, '$.completionPolicy.evidenceRule')) != 'FOUR_STORE_REDEEM' join coop_order o on o.topic_id = t.id and o.to_type = 'merchant' and o.status = 0 and o.del_flag = 0 where exists (select 1 from redemption rd join cms_registration r on r.id = rd.registration_id where r.owner_type = 2 and r.owner_id = a.id and rd.topic_id = t.id and rd.merchant_id = o.to_id and rd.status = 'ACTIVE') ) gv join cms_activity a on a.id = gv.activity_id join cms_topic t on t.id = a.topic_id join coop_order o on o.id = gv.coop_order_id and o.to_type = 'merchant' and o.to_id = gv.merchant_member_id and o.status = 0 and o.del_flag = 0 and o.share_mode = 2 where a.is_settlement = 0 and a.del_flag = 0 and a.status = 1 and a.club_id > 0
and gv.merchant_member_id = #{merchantMemberId}
and gv.activity_id in #{activityId}
union all select a.id as activityId, f.merchantId as merchantMemberId, a.end_date as endDate, min(f.fee) * count(distinct r.id) as amount from cms_activity a join cms_topic t on t.id = a.topic_id and t.product_type = 2 join topic_sale_snapshot ss on ss.topic_id = t.id and ss.schema_version = 'CANONICAL_15_V1' join json_table(ss.canonical_json, '$.merchantCashSettlementMode.offers[*]' columns ( offerId bigint path '$.id', merchantId bigint path '$.merchantId', payerClubId bigint path '$.payerClubId', termsMode varchar(16) path '$.termsMode', fee decimal(12,2) path '$.perHeadFee')) f on f.termsMode = 'REVSHARE' and f.payerClubId = a.club_id join cms_registration r on r.owner_type = 2 and r.owner_id = a.id and r.payment_status = 2 and r.registration_status = 2 where a.is_settlement = 0 and a.del_flag = 0 and a.status = 1 and a.club_id > 0 and a.club_id = t.club_id and json_unquote(json_extract(ss.canonical_json, '$.completionPolicy.evidenceRule')) != 'FOUR_STORE_REDEEM' and exists (select 1 from redemption rd where rd.registration_id = r.id and rd.topic_id = t.id and rd.merchant_id = f.merchantId and rd.status = 'ACTIVE') and not exists (select 1 from refund_application ra where ra.source_type = 'registration' and ra.source_id = r.id and ra.status = 1 and ra.del_flag = 0) and f.merchantId = #{merchantMemberId}
and a.id in #{activityId}
group by a.id, f.merchantId, a.end_date having min(f.fee) = max(f.fee) order by activityId, merchantMemberId
